	// ①② 同一本账本中登记两个费率项的同名版本 v1：
	//    seat/v1 单价 150 分、room/v1 单价 300 分，有效期都是 [2026-03-01, 2026-03-31)。
	seatV1End := v1End
	must(book.RegisterVersion(tariff.RegisterRequest{
		ItemID: "seat", VersionID: "v1", UnitPrice: 150, Start: v1Start, End: &seatV1End,
	}))
	roomV1End := v1End
	must(book.RegisterVersion(tariff.RegisterRequest{
		ItemID: "room", VersionID: "v1", UnitPrice: 300, Start: v1Start, End: &roomV1End,
	}))
