	//    替代来源按本次登记指定的费率项 seat 查找，截短的只是 seat/v1。
	must(book.RegisterVersion(tariff.RegisterRequest{
		ItemID: "seat", VersionID: "v2", UnitPrice: 180, Start: v2Start, Replaces: "v1",
