		errors.Is(err, tariff.ErrReplaceTargetNotFound))

	// ⑪ ⑨⑩ 两次失败同样整次回滚，两项的版本信息仍与④完全一致。
	printViews(book, "⑪ ⑨⑩ 两次失败登记后的版本视图（仍与④完全一致）")
