		ItemID:    "seat",
		VersionID: "v1",
		UnitPrice: 150,
		Start:     v1Start,
		End:       &seatV1End,
	}); err != nil {
		panic(err)
	}
	roomV1End := v1End
	if err := book.RegisterVersion(tariff.RegisterRequest{
		ItemID:    "room",
		VersionID: "v1",
		UnitPrice: 300,
		Start:     v1Start,
		End:       &roomV1End,
	}); err != nil {
		panic(err)
	}
	printViews(book, "①② seat 与 room 各自登记 v1 后的版本视图")

